<?php use App\Support\App;$u=App::requireAuth();$gs=App::db()->query('SELECT code,name FROM payment_gateways WHERE is_active=1')->fetchAll();$title='Deposit';require __DIR__.'/../layouts/head.php';require __DIR__.'/../components/app_start.php';?><h1 class="page-title">Add balance</h1><p class="page-sub">Tambah saldo untuk melakukan order layanan.</p><div class="grid lg:grid-cols-[1fr_.55fr] gap-5 mt-6"><form id="d" class="saas-card p-5 sm:p-6 space-y-5"><input type="hidden" id="csrf" value="<?=App::csrf()?>"><div><label class="text-sm font-semibold">Amount</label><div class="relative mt-2"><span class="absolute left-3 top-3 text-zinc-500">Rp</span><input class="field !pl-10 text-lg font-semibold" name="amount" type="number" min="1000" placeholder="100000" required></div></div><div><label class="text-sm font-semibold">Payment method</label><select class="field mt-2" name="gateway"><?php foreach($gs as $g):?><option value="<?=$g['code']?>"><?=htmlspecialchars($g['name'])?></option><?php endforeach?></select></div><button class="btn btn-dark w-full sm:w-auto"><i data-lucide="credit-card"></i>Continue payment</button></form><div class="saas-card p-5 h-fit"><span class="text-xs text-zinc-500">CURRENT BALANCE</span><div class="text-3xl font-bold tracking-tight mt-2">Rp<?=number_format($u['balance'],0,',','.')?></div><p class="text-sm text-zinc-500 mt-4">Saldo masuk setelah pembayaran berhasil diverifikasi.</p></div></div><script>d.onsubmit=async e=>{e.preventDefault();let r=await fetch('/api/deposits',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf.value},body:JSON.stringify(Object.fromEntries(new FormData(d)))}),j=await r.json();Swal.fire(j.ok?'Deposit created':'Deposit failed',j.message||'Request berhasil dibuat',j.ok?'success':'error')}</script><?php require __DIR__.'/../components/app_end.php';require __DIR__.'/../layouts/foot.php';?>